<script setup>import {onMounted,reactive,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useAuth} from '../../stores/auth.js';import {useToast} from '../../stores/toast.js';const mode=ref('login'),showPassword=ref(false),busy=ref(false),form=reactive({fullName:'',phone:'',email:'',password:''});const auth=useAuth(),router=useRouter(),route=useRoute(),toast=useToast();onMounted(()=>{if(route.query.mode==='register')mode.value='register'});async function submit(){busy.value=true;try{const user=mode.value==='login'?await auth.login(form):await auth.register(form);toast.show(mode.value==='login'?'Đăng nhập thành công':'Đăng ký thành công');router.push(route.query.redirect||'/')}catch(e){toast.show(e.message)}finally{busy.value=false}}</script>
<template><section class="auth-page"><div class="auth-visual"><span class="kicker">FASTTRAVEL MEMBER</span><h1>Mỗi hành trình<br>là một câu chuyện.</h1><p>Đăng nhập để quản lý vé, nhận ưu đãi và đặt chỗ nhanh hơn.</p></div><div class="auth-card"><RouterLink class="logo mini" to="/"><span>F</span>FASTTRAVEL</RouterLink><h2>{{mode==='login'?'Chào mừng trở lại':'Tạo tài khoản'}}</h2><form @submit.prevent="submit"><div v-if="mode==='register'" class="form-grid"><label>Họ và tên<input v-model="form.fullName" required></label><label>Số điện thoại<input v-model="form.phone" pattern="0[0-9]{9}" required></label></div><label>Email<input v-model="form.email" type="email" required></label><label>Mật khẩu<div class="password"><input v-model="form.password" :type="showPassword?'text':'password'" minlength="6" required><button type="button" @click="showPassword=!showPassword">{{showPassword?'Ẩn':'Hiện'}}</button></div></label><button class="btn primary full" :disabled="busy">{{busy?'Đang xử lý...':mode==='login'?'Đăng nhập':'Đăng ký miễn phí'}}</button></form><button class="switch" @click="mode=mode==='login'?'register':'login'">{{mode==='login'?'Chưa có tài khoản? Đăng ký ngay':'Đã có tài khoản? Đăng nhập'}}</button></div></section></template>
